let products = [
  { id: 1, name: 'Laptop', price: 999, inventory: 42, available: true },
  { id: 2, name: 'Phone', price: 699, inventory: 128, available: true },
  { id: 3, name: 'Tablet', price: 499, inventory: 0, available: false },
  { id: 4, name: 'Headphones', price: 199, inventory: 256, available: true },
  { id: 5, name: 'Watch', price: 299, inventory: 15, available: true },
]

let syncVersion = 1
let isSyncing = false
let lastSyncedAt = Date.now()

export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return [...products]
}

export async function syncCatalog() {
  if (isSyncing) {
    return { skipped: true }
  }

  isSyncing = true

  try {
    await new Promise((resolve) => setTimeout(resolve, 5000))
    syncVersion++

    products = [
      { id: 1, name: 'Laptop Pro', price: 1099, inventory: 35, available: true },
      { id: 2, name: 'Phone X', price: 799, inventory: 150, available: true },
      { id: 3, name: 'Tablet Air', price: 549, inventory: 20, available: true },
      { id: 4, name: 'Headphones Pro', price: 249, inventory: 200, available: true },
      { id: 5, name: 'Watch Ultra', price: 399, inventory: 10, available: true },
    ]

    lastSyncedAt = Date.now()
    return { success: true, syncVersion }
  } finally {
    isSyncing = false
  }
}

export function getSyncStatus() {
  return { isSyncing, lastSyncedAt, syncVersion }
}

