import { revalidateTag, cacheTag } from "next/cache"
import { getAllProducts, syncCatalog, getSyncStatus } from "@/lib/db"

async function getCachedProducts() {
  "use cache"
  cacheTag("products")
  return getAllProducts()
}

export default function CatalogPage() {
  async function handleSync(_formData: FormData) {
    "use server"
    revalidateTag("products")
    syncCatalog()
  }

  const { isSyncing, lastSyncedAt, syncVersion } = getSyncStatus()

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", padding: "2rem", maxWidth: "900px", margin: "0 auto" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "1.5rem" }}>
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: "0.25rem 0 0", color: "#666", fontSize: "0.875rem" }}>
            Sync v{syncVersion} &middot; Last synced: {new Date(lastSyncedAt).toLocaleTimeString()}
            {isSyncing && " \u00b7 Syncing in progress\u2026"}
          </p>
        </div>
        <form action={handleSync}>
          <button
            type="submit"
            disabled={isSyncing}
            style={{
              padding: "0.5rem 1.25rem",
              fontSize: "0.875rem",
              fontWeight: 500,
              border: "1px solid #d1d5db",
              borderRadius: "0.375rem",
              background: isSyncing ? "#f3f4f6" : "#fff",
              cursor: isSyncing ? "not-allowed" : "pointer",
            }}
          >
            {isSyncing ? "Syncing\u2026" : "Sync latest catalog"}
          </button>
        </form>
      </div>

      <ProductTable />
    </div>
  )
}

async function ProductTable() {
  const products = await getCachedProducts()

  return (
    <table style={{ width: "100%", borderCollapse: "collapse" }}>
      <thead>
        <tr style={{ borderBottom: "2px solid #e5e7eb", textAlign: "left" }}>
          <th style={{ padding: "0.75rem 0.5rem" }}>ID</th>
          <th style={{ padding: "0.75rem 0.5rem" }}>Name</th>
          <th style={{ padding: "0.75rem 0.5rem" }}>Price</th>
          <th style={{ padding: "0.75rem 0.5rem" }}>Inventory</th>
          <th style={{ padding: "0.75rem 0.5rem" }}>Available</th>
        </tr>
      </thead>
      <tbody>
        {products.map((p) => (
          <tr key={p.id} style={{ borderBottom: "1px solid #e5e7eb" }}>
            <td style={{ padding: "0.75rem 0.5rem" }}>{p.id}</td>
            <td style={{ padding: "0.75rem 0.5rem" }}>{p.name}</td>
            <td style={{ padding: "0.75rem 0.5rem" }}>${p.price}</td>
            <td style={{ padding: "0.75rem 0.5rem" }}>{p.inventory}</td>
            <td style={{ padding: "0.75rem 0.5rem" }}>{p.available ? "\u2705" : "\u274c"}</td>
          </tr>
        ))}
      </tbody>
    </table>
  )
}

